<template>
  <div class="tab-page">
    <el-form :inline="true" :model="query" size="small" class="filter-form">
      <el-form-item label="游戏名称"><el-input v-model="query.name" clearable /></el-form-item><el-form-item label="支持平台"><el-select v-model="query.platform" clearable><el-option v-for="item in platforms" :key="item" :label="item" :value="item" /></el-select></el-form-item>
      <el-form-item label="状态"><el-select v-model="query.status" clearable><el-option label="启用" value="enabled" /><el-option label="停用" value="disabled" /><el-option label="维护中" value="maintenance" /></el-select></el-form-item>
      <el-form-item label="游戏场馆"><el-select v-model="query.venueId" clearable filterable><el-option v-for="item in state.venues" :key="item.id" :label="item.nameZh" :value="item.id" /></el-select></el-form-item>
      <el-form-item label="场馆类型"><el-select v-model="query.venueType" clearable><el-option v-for="item in venueTypeOptions" :key="item.name" :label="item.name" :value="item.name" /></el-select></el-form-item>
      <el-form-item label="游戏CODE"><el-input v-model="query.code" clearable /></el-form-item><el-form-item label="品牌"><el-input v-model="query.brand" clearable /></el-form-item>
      <el-form-item><el-button type="primary" @click="search">筛选</el-button><el-button @click="resetQuery">重置</el-button></el-form-item>
    </el-form>
    <div class="toolbar"><el-button type="success" size="small" @click="openCreate">新增游戏</el-button><el-button type="primary" size="small" @click="openBatch">批量新增游戏</el-button></div>
    <el-table :data="page.rows" border stripe size="mini">
      <el-table-column type="index" label="序号" width="55" /><el-table-column prop="name" label="游戏名称" min-width="120" /><el-table-column label="游戏场馆" width="110"><template slot-scope="s">{{ venueName(s.row.venueId) }}</template></el-table-column><el-table-column label="场馆类型" width="90"><template slot-scope="s">{{ venueType(s.row.venueId) }}</template></el-table-column>
      <el-table-column prop="code" label="游戏CODE" width="110" /><el-table-column label="支持平台" min-width="120"><template slot-scope="s">{{ s.row.platforms.join(' / ') }}</template></el-table-column><el-table-column prop="sort" label="排序" width="60" />
      <el-table-column label="WEB游戏图片" width="105"><template slot-scope="s"><el-image class="thumb" :src="gameImageUrl(s.row.webImage)" :preview-src-list="[gameImageUrl(s.row.webImage)]" /></template></el-table-column><el-table-column label="H5游戏图片" width="100"><template slot-scope="s"><el-image class="thumb" :src="gameImageUrl(s.row.h5Image)" :preview-src-list="[gameImageUrl(s.row.h5Image)]" /></template></el-table-column>
      <el-table-column label="授权数" width="70"><template slot-scope="s"><el-button type="text" @click="openAuthorizedSites(s.row)">{{ gameAuthCount(s.row) }}</el-button></template></el-table-column><el-table-column label="游戏状态" width="85"><template slot-scope="s"><el-tag size="mini" :type="s.row.status === 'enabled' ? 'success' : s.row.status === 'maintenance' ? 'warning' : 'info'">{{ statusLabel(s.row.status) }}</el-tag></template></el-table-column><el-table-column prop="brand" label="品牌" width="80" /><el-table-column prop="creator" label="创建人" width="90" /><el-table-column prop="createdAt" label="创建时间" width="150" /><el-table-column prop="editor" label="最后编辑人" width="100" /><el-table-column prop="editedAt" label="最后编辑时间" width="150" />
      <el-table-column label="操作" fixed="right" width="220"><template slot-scope="s"><el-button type="text" size="mini" @click="openEdit(s.row)">编辑</el-button><el-button type="text" size="mini" @click="openStatus(s.row)">切换状态</el-button><el-button type="text" size="mini" @click="openAuthorization(s.row,'authorize')">授权</el-button><el-button type="text" size="mini" @click="openAuthorization(s.row,'revoke')">取消授权</el-button></template></el-table-column>
    </el-table>
    <pagination v-show="page.total>0" :total="page.total" :page.sync="pageNum" :limit.sync="pageSize" @pagination="syncPage" />

    <el-dialog :title="editingId ? '编辑游戏' : '新增游戏'" :visible.sync="dialogVisible" width="660px" append-to-body><el-form :model="form" label-width="120px" size="small">
      <el-form-item label="游戏名称" required><el-input v-model.trim="form.name" /></el-form-item><el-form-item label="游戏场馆" required><el-select v-model="form.venueId" filterable class="full"><el-option v-for="item in state.venues" :key="item.id" :label="item.nameZh" :value="item.id" /></el-select></el-form-item><el-form-item label="场馆类型"><el-input :value="venueType(form.venueId)" disabled /></el-form-item><el-form-item label="游戏CODE" required><el-input v-model.trim="form.code" /></el-form-item>
      <el-form-item label="支持平台" required><el-checkbox-group v-model="form.platforms"><el-checkbox v-for="item in platforms" :key="item" :label="item" /></el-checkbox-group></el-form-item><el-form-item label="排序" required><el-input-number v-model="form.sort" :min="1" class="full" /></el-form-item>
      <el-form-item label="WEB游戏图片"><image-upload v-model="form.webImage" :limit="1" :file-size="2" :file-type="['jpg','jpeg','png']" :is-show-tip="false" :drag="false" replace-on-exceed /></el-form-item><el-form-item label="H5游戏图片"><image-upload v-model="form.h5Image" :limit="1" :file-size="2" :file-type="['jpg','jpeg','png']" :is-show-tip="false" :drag="false" replace-on-exceed /></el-form-item><el-form-item label="品牌"><el-input v-model.trim="form.brand" /></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status" class="game-status-options"><el-radio label="enabled">启用</el-radio><el-radio label="maintenance">维护中</el-radio><el-radio label="disabled">停用</el-radio></el-radio-group></el-form-item>
      <template v-if="form.status === 'maintenance'"><el-form-item label="维护起始时间" required><el-date-picker v-model="form.maintenanceConfig.startDate" type="date" value-format="yyyy-MM-dd" format="yyyy-MM-dd" placeholder="请选择维护起始时间" class="full" /></el-form-item><el-form-item label="维护结束时间" required><el-date-picker v-model="form.maintenanceConfig.endDate" type="date" value-format="yyyy-MM-dd" format="yyyy-MM-dd" placeholder="请选择维护结束时间" class="full" /></el-form-item><el-form-item label="原因备注"><el-input v-model.trim="form.maintenanceConfig.reason" type="textarea" :rows="3" :maxlength="50" show-word-limit placeholder="请填写维护原因，不超过50字" /></el-form-item><el-form-item label="维护展示时间" required><el-radio-group v-model="form.maintenanceConfig.showMaintenanceTime"><el-radio :label="true">展示</el-radio><el-radio :label="false">不展示</el-radio></el-radio-group></el-form-item></template>
    </el-form><span slot="footer"><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" @click="submit">提交</el-button></span></el-dialog>

    <el-dialog title="批量新增游戏" :visible.sync="batchVisible" width="1060px" append-to-body><el-button type="primary" size="mini" @click="addBatchRow">新增一行</el-button><el-table :data="batchRows" border size="mini" class="batch-table"><el-table-column label="游戏名称"><template slot-scope="s"><el-input v-model="s.row.name" /></template></el-table-column><el-table-column label="游戏场馆" width="150"><template slot-scope="s"><el-select v-model="s.row.venueId"><el-option v-for="v in state.venues" :key="v.id" :label="v.nameZh" :value="v.id" /></el-select></template></el-table-column><el-table-column label="游戏CODE"><template slot-scope="s"><el-input v-model="s.row.code" /></template></el-table-column><el-table-column label="支持平台" width="190"><template slot-scope="s"><el-select v-model="s.row.platforms" multiple><el-option v-for="p in platforms" :key="p" :label="p" :value="p" /></el-select></template></el-table-column><el-table-column label="排序" width="100"><template slot-scope="s"><el-input-number v-model="s.row.sort" :min="1" :controls="false" /></template></el-table-column><el-table-column label="品牌"><template slot-scope="s"><el-input v-model="s.row.brand" /></template></el-table-column><el-table-column label="操作" width="70"><template slot-scope="s"><el-button type="text" @click="batchRows.splice(s.$index,1)">删除</el-button></template></el-table-column></el-table><span slot="footer"><el-button @click="batchVisible=false">取消</el-button><el-button type="primary" @click="submitBatch">提交</el-button></span></el-dialog>

    <el-dialog title="切换游戏状态" :visible.sync="statusVisible" width="650px" append-to-body custom-class="game-status-dialog">
      <div v-if="currentStatusGame" class="game-status-body">
        <div class="game-status-row"><span>游戏名称：</span><strong>{{ currentStatusGame.name }} / {{ currentStatusGame.code }}</strong></div>
        <div class="game-status-row"><span>设置游戏状态：</span><el-radio-group v-model="statusForm.status" class="game-status-options"><el-radio label="enabled">启用</el-radio><el-radio label="maintenance">维护中</el-radio><el-radio label="disabled">停用</el-radio></el-radio-group></div>
        <div v-if="statusForm.status === 'maintenance'" class="game-maintenance-settings">
          <div class="game-status-row"><span class="required-label">维护起始时间：</span><el-date-picker v-model="statusForm.maintenanceConfig.startDate" type="date" value-format="yyyy-MM-dd" format="yyyy-MM-dd" placeholder="请选择维护起始时间" /></div>
          <div class="game-status-row"><span class="required-label">维护结束时间：</span><el-date-picker v-model="statusForm.maintenanceConfig.endDate" type="date" value-format="yyyy-MM-dd" format="yyyy-MM-dd" placeholder="请选择维护结束时间" /></div>
          <div class="game-status-row"><span>原因备注：</span><el-input v-model.trim="statusForm.maintenanceConfig.reason" type="textarea" :rows="4" :maxlength="50" show-word-limit placeholder="请填写维护原因，不超过50字" class="game-maintenance-reason" /></div>
          <div class="game-status-row"><span class="required-label">维护展示时间：</span><el-radio-group v-model="statusForm.maintenanceConfig.showMaintenanceTime"><el-radio :label="true">展示</el-radio><el-radio :label="false">不展示</el-radio></el-radio-group></div>
        </div>
      </div>
      <span slot="footer"><el-button @click="statusVisible=false">取消</el-button><el-button type="primary" @click="submitStatus">提交</el-button></span>
    </el-dialog>

    <el-dialog :title="authorizationTitle" :visible.sync="authorizationVisible" width="720px" append-to-body custom-class="game-authorization-dialog">
      <div v-loading="siteLoading" class="authorization-body">
        <el-form :inline="true" :model="authorizationQuery" size="small" label-width="95px" class="authorization-filter">
          <el-form-item label="站点ID/编号"><el-input v-model.trim="authorizationQuery.keyword" clearable placeholder="站点ID或站点编号" /></el-form-item>
          <el-form-item label="站点名称"><el-input v-model.trim="authorizationQuery.name" clearable placeholder="站点名称" /></el-form-item>
          <el-form-item label="站点ID范围" class="range-item"><el-input-number v-model="authorizationQuery.startId" :controls="false" placeholder="开始站点ID" /><span class="range-separator">至</span><el-input-number v-model="authorizationQuery.endId" :controls="false" placeholder="结束站点ID" /></el-form-item>
          <el-form-item label="数据库ID"><el-input-number v-model="authorizationQuery.databaseId" :controls="false" placeholder="请输入数据库ID" /></el-form-item>
          <el-form-item class="authorization-actions"><el-button type="primary" @click="applyAuthorizationFilter">筛选</el-button><el-button @click="resetAuthorizationFilter">重置</el-button></el-form-item>
        </el-form>
        <div class="site-selection">
          <el-checkbox :value="allFilteredSelected" :indeterminate="selectionIndeterminate" @change="toggleAllFiltered">全部</el-checkbox>
          <el-checkbox-group v-model="selectedSiteCodes" class="site-checkboxes"><el-checkbox v-for="site in filteredAuthorizationSites" :key="site.code" :label="site.code">{{ site.name }}（{{ site.code }}）</el-checkbox></el-checkbox-group>
          <el-empty v-if="!siteLoading && !filteredAuthorizationSites.length" description="暂无符合条件的站点" :image-size="70" />
        </div>
      </div>
      <span slot="footer"><el-button @click="authorizationVisible=false">取消</el-button><el-button type="primary" :loading="siteLoading" @click="submitAuthorization">确定</el-button></span>
    </el-dialog>

    <el-dialog :title="authorizedSitesTitle" :visible.sync="authorizedSitesVisible" width="560px" append-to-body>
      <el-table v-loading="authorizedSitesLoading" :data="authorizedSiteRows" border stripe size="mini" empty-text="该游戏暂未授权站点">
        <el-table-column type="index" label="序号" width="70" align="center" />
        <el-table-column prop="name" label="站点名称" min-width="180" />
        <el-table-column prop="code" label="站点编号" min-width="150" />
      </el-table>
      <span slot="footer"><el-button type="primary" @click="authorizedSitesVisible=false">关闭</el-button></span>
    </el-dialog>
  </div>
</template>

<script>
import ImageUpload from '@/components/ImageUpload'
import { listSite } from '@/api/site/site'
const { DEMO_IMAGE, cloneState, defaultMaintenanceConfig, validateMaintenanceConfig, filterGames, filterAuthorizationSites, normalizeSiteRows, paginate, validateGame, validateGameBatch, authorizeGameSites, revokeGameSites, getGameAuthCount, appendMaintenanceLog } = require('./model')
const emptyGame = () => ({ id: null, name: '', venueId: '', code: '', platforms: ['H5'], sort: 1, webImage: DEMO_IMAGE, h5Image: DEMO_IMAGE, authCount: 0, authorizedSiteCodes: [], status: 'enabled', maintenanceConfig: defaultMaintenanceConfig(), brand: '', creator: '演示管理员', createdAt: '', editor: '演示管理员', editedAt: '' })
const emptyAuthorizationQuery=()=>({keyword:'',name:'',startId:undefined,endId:undefined,databaseId:undefined})
const publicBase=String(process.env.BASE_URL||'/').replace(/\/?$/,'/')
const resolveGameImage=value=>{const path=String(value||'');if(!path||/^(?:https?:)?\/\//.test(path)||/^(?:data|blob):/.test(path))return path;if(path.startsWith('/profile/'))return`${publicBase}prototype-api${path}`;if(path.startsWith('/prototype-api/'))return`${publicBase}${path.slice(1)}`;return path}
export default { name:'GameList', components:{ImageUpload}, props:{state:{type:Object,required:true},presetVenueId:{type:[Number,String],default:''}}, data(){return{platforms:['PC','H5','APP'],query:{name:'',platform:'',status:'',venueId:'',venueType:'',code:'',brand:''},appliedQuery:{},pageNum:1,pageSize:10,dialogVisible:false,batchVisible:false,editingId:null,form:emptyGame(),batchRows:[],statusVisible:false,statusGameId:null,statusForm:{status:'enabled',maintenanceConfig:defaultMaintenanceConfig()},authorizationVisible:false,authorizationMode:'authorize',authorizationGameId:null,authorizationQuery:emptyAuthorizationQuery(),appliedAuthorizationQuery:{},siteRows:[],selectedSiteCodes:[],siteLoading:false,authorizedSitesVisible:false,authorizedSitesGameId:null,authorizedSitesLoading:false,authorizedSitesSource:[]}}, watch:{presetVenueId:{immediate:true,handler(value){if(value){this.query.venueId=value;this.search()}}}}, computed:{venueTypeOptions(){return(this.state.venueTypes||[]).slice().sort((a,b)=>Number(a.sort||0)-Number(b.sort||0))},enrichedGames(){return this.state.games.map(row=>({...row,venueType:this.venueType(row.venueId)}))},page(){return paginate(filterGames(this.enrichedGames,this.appliedQuery),this.pageNum,this.pageSize)},currentStatusGame(){return this.state.games.find(item=>item.id===this.statusGameId)||null},currentAuthorizationGame(){return this.state.games.find(item=>item.id===this.authorizationGameId)||null},currentAuthorizationVenue(){return this.currentAuthorizationGame?this.venue(this.currentAuthorizationGame.venueId):null},authorizationTitle(){const name=this.currentAuthorizationGame?this.currentAuthorizationGame.name:'';return this.authorizationMode==='authorize'?`游戏授权 - ${name}`:`取消游戏授权 - ${name}`},currentAuthorizedSitesGame(){return this.state.games.find(item=>item.id===this.authorizedSitesGameId)||null},authorizedSitesTitle(){return`已授权站点 - ${this.currentAuthorizedSitesGame?this.currentAuthorizedSitesGame.name:''}`},authorizedSiteRows(){const game=this.currentAuthorizedSitesGame;if(!game)return[];const sites=new Map(this.authorizedSitesSource.map(site=>[site.code,site]));return(game.authorizedSiteCodes||[]).map(code=>sites.get(code)||{code,name:code})},authorizationCandidates(){const venueCodes=new Set((this.currentAuthorizationVenue&&this.currentAuthorizationVenue.authorizedSiteCodes)||[]);const gameCodes=new Set((this.currentAuthorizationGame&&this.currentAuthorizationGame.authorizedSiteCodes)||[]);return this.siteRows.filter(site=>this.authorizationMode==='authorize'?venueCodes.has(site.code)&&!gameCodes.has(site.code):gameCodes.has(site.code))},filteredAuthorizationSites(){return filterAuthorizationSites(this.authorizationCandidates,this.appliedAuthorizationQuery)},filteredSiteCodes(){return this.filteredAuthorizationSites.map(site=>site.code)},selectedFilteredCount(){const selected=new Set(this.selectedSiteCodes);return this.filteredSiteCodes.filter(code=>selected.has(code)).length},allFilteredSelected(){return this.filteredSiteCodes.length>0&&this.selectedFilteredCount===this.filteredSiteCodes.length},selectionIndeterminate(){return this.selectedFilteredCount>0&&!this.allFilteredSelected}}, methods:{gameImageUrl(value){return resolveGameImage(value)},venue(rowId){return this.state.venues.find(v=>v.id===rowId)},venueName(id){return(this.venue(id)||{}).nameZh||'-'},venueType(id){return(this.venue(id)||{}).type||'-'},gameAuthCount(row){return getGameAuthCount(row)},statusLabel(v){return({enabled:'启用',disabled:'停用',maintenance:'维护中'})[v]},search(){this.appliedQuery=cloneState(this.query);this.pageNum=1},resetQuery(){this.query={name:'',platform:'',status:'',venueId:'',venueType:'',code:'',brand:''};this.search()},syncPage({page,limit}){this.pageNum=page;this.pageSize=limit},openCreate(){this.editingId=null;this.form=emptyGame();this.dialogVisible=true},openEdit(row){this.editingId=row.id;this.form={...cloneState(row),maintenanceConfig:{...defaultMaintenanceConfig(),...(row.maintenanceConfig||{})}};this.dialogVisible=true},stamp(row){const time=new Date().toISOString().slice(0,19).replace('T',' ');row.editedAt=time;row.editor='演示管理员';if(!row.createdAt)row.createdAt=time},submit(){const r=validateGame(this.form,this.state.games,this.editingId);if(!r.valid)return this.$message.warning(r.message);if(this.form.status==='maintenance'){const maintenanceResult=validateMaintenanceConfig(this.form.maintenanceConfig);if(!maintenanceResult.valid)return this.$message.warning(maintenanceResult.message)}this.stamp(this.form);if(this.editingId)Object.assign(this.state.games.find(i=>i.id===this.editingId),cloneState(this.form));else{this.form.id=Math.max(0,...this.state.games.map(i=>Number(i.id)))+1;this.state.games.unshift(cloneState(this.form))}this.$emit('state-change');this.dialogVisible=false;this.$modal.msgSuccess('游戏保存成功')},openBatch(){this.batchRows=[emptyGame()];this.batchVisible=true},addBatchRow(){this.batchRows.push(emptyGame())},submitBatch(){const r=validateGameBatch(this.batchRows,this.state.games);if(!r.valid)return this.$message.warning(r.message);let next=Math.max(0,...this.state.games.map(i=>Number(i.id)))+1;this.batchRows.forEach(row=>{row.id=next++;this.stamp(row);this.state.games.unshift(cloneState(row))});this.$emit('state-change');this.batchVisible=false;this.$modal.msgSuccess('批量新增游戏成功')},openStatus(row){this.statusGameId=row.id;this.statusForm={status:row.status,maintenanceConfig:{...defaultMaintenanceConfig(),...(row.maintenanceConfig||{})}};this.statusVisible=true},submitStatus(){const row=this.currentStatusGame;if(!row)return;if(this.statusForm.status==='maintenance'){const config=this.statusForm.maintenanceConfig;const result=validateMaintenanceConfig(config);if(!result.valid)return this.$message.warning(result.message);row.maintenanceConfig=cloneState(config);appendMaintenanceLog(this.state,{venueId:row.venueId,gameId:row.id,startAt:config.startDate,endAt:config.endDate,reason:config.reason||'游戏维护'})}const changed=row.status!==this.statusForm.status;if(changed)row.status=this.statusForm.status;if(changed||this.statusForm.status==='maintenance'){this.stamp(row);this.$emit('state-change')}this.statusVisible=false;this.$modal.msgSuccess('游戏状态已更新')},async openAuthorizedSites(row){this.authorizedSitesGameId=row.id;this.authorizedSitesSource=[];this.authorizedSitesVisible=true;this.authorizedSitesLoading=true;try{const response=await listSite({pageNum:1,pageSize:1000});this.authorizedSitesSource=normalizeSiteRows((response&&response.rows)||[])}catch(error){this.$message.error('站点列表获取失败')}finally{this.authorizedSitesLoading=false}},async openAuthorization(row,mode){this.authorizationGameId=row.id;this.authorizationMode=mode;this.authorizationQuery=emptyAuthorizationQuery();this.appliedAuthorizationQuery={};this.selectedSiteCodes=[];this.authorizationVisible=true;this.siteLoading=true;try{const response=await listSite({pageNum:1,pageSize:1000});this.siteRows=normalizeSiteRows((response&&response.rows)||[])}catch(error){this.authorizationVisible=false;this.$message.error('站点列表获取失败')}finally{this.siteLoading=false}},applyAuthorizationFilter(){this.appliedAuthorizationQuery=cloneState(this.authorizationQuery)},resetAuthorizationFilter(){this.authorizationQuery=emptyAuthorizationQuery();this.appliedAuthorizationQuery={};this.selectedSiteCodes=[]},toggleAllFiltered(checked){const visible=new Set(this.filteredSiteCodes);const selected=new Set(this.selectedSiteCodes);if(checked)visible.forEach(code=>selected.add(code));else visible.forEach(code=>selected.delete(code));this.selectedSiteCodes=Array.from(selected)},submitAuthorization(){const game=this.currentAuthorizationGame;if(!game)return;if(!this.selectedSiteCodes.length)return this.$message.warning(`请选择需要${this.authorizationMode==='authorize'?'授权':'取消授权'}的站点`);if(this.authorizationMode==='authorize')authorizeGameSites(game,this.currentAuthorizationVenue,this.selectedSiteCodes);else revokeGameSites(game,this.selectedSiteCodes);this.stamp(game);this.$emit('state-change');this.authorizationVisible=false;this.$modal.msgSuccess(this.authorizationMode==='authorize'?'授权成功':'取消授权成功')}}}
</script>
